<?php
use EIPSI\StudyEngine\Longitudinal as L;
use EIPSI\StudyEngine\Persistence as P;
use EIPSI\StudyEngine\Runtime as R;
use EIPSI\StudyEngine\Contracts\Canonical;
pf_case('F HTTP matching cookie never bypasses explicit email access',function(){list($p,$h,$cookies,$email)=pf_http_enroll();$entry=pf_http($p['public']);$req=pe_http_request($entry,'enroll');$req['email']=$email;$req['csrf']=L\Identity::csrf($p['public'],$cookies[0]->value);$before=count(pf_intents(pf_http_frame($p,$h,$cookies)['access']['execution_id'],'VERIFY_PARTICIPANT'));$r=pf_http($p['public'],$cookies,$req);pe_assert($r['status']===200&&$r['data']['state']==='EMAIL_ENTRY','Cookie bypassed email validation');pe_assert(count(pf_intents(pf_http_frame($p,$h,$cookies)['access']['execution_id'],'VERIFY_PARTICIPANT'))===$before+1,'No access link intent');});
pf_case('F HTTP validation link keeps the future assessment closed',function(){
 $d=L\Configuration::apply(pe_definition(),array('verification_policy'=>'ALLOW_UNVERIFIED','immediate_availability_policy'=>'SEND'));foreach($d['nodes'] as &$n)if($n['id']==='E_ASSESSMENT')$n['schedule']['temporal_rule']=array('kind'=>'OFFSET','duration'=>array('kind'=>'ELAPSED','seconds'=>3600));unset($n);$p=pe_publish('simple',false,pe_native_transport_fixture($d));$entry=pf_http($p['public']);$request=pe_http_request($entry,'enroll');$request['email']='http-wait@example.test';$h=pf_http($p['public'],$entry['cookies'],$request);pe_assert($h['status']===200&&$h['data']['state']==='WAIT','No HTTP WAIT');$cookies=$h['cookies']?:$entry['cookies'];$frame=pf_http_frame($p,$h,$cookies);pe_assert(count(pf_intents($frame['access']['execution_id'],'ASSESSMENT_AVAILABLE'))===1,'No future availability intent');$target=$frame['view']['next_action']['payload']['target']['node_id'];$instance=null;foreach($frame['view']['snapshot']['instances'] as $i)if($i['definition_id']===$target)$instance=$i['id'];$cap=pf_http_cap($frame,'VERIFY_PARTICIPANT',$instance);$r=pf_http($p['public'],array(),null,$cap);pe_assert($r['status']===303,'No exchange');$wait=pf_http($p['public'],$r['cookies']);pe_assert($wait['status']===200&&$wait['data']['state']==='WAIT'&&strpos($wait['data']['html'],'eipsi-native-assessment-frame')===false,'Future assessment opened early');pe_assert((new L\Identity(pf_db()))->participant($frame['access']['participant_id'])['verification_state']==='VERIFIED','Link did not validate email');
});
pf_case('F HTTP existing no session access email click restores same execution',function(){list($p,$h,$cookies,$email)=pf_http_enroll();$f=pf_http_frame($p,$h,$cookies);$entry=pf_http($p['public']);$r=pe_http_request($entry,'enroll');$r['email']=$email;$generic=pf_http($p['public'],$entry['cookies'],$r);pe_assert($generic['data']['state']==='EMAIL_ENTRY','No generic response');$intent=pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT')[0];$old=$GLOBALS['pf_now'];$GLOBALS['pf_now']=(new L\Clock())->now();try{pe_assert(pf_delivery($intent)['success'],'Access email failed');$exchange=pf_http($p['public'],array(),null,pf_link(end($GLOBALS['m0_mail'])));pe_assert($exchange['status']===303,'Exchange failed');$state=pf_http($p['public'],$exchange['cookies']);$next=pf_http_frame($p,$state,$exchange['cookies']);pe_assert($state['data']['state']==='OPEN_ASSESSMENT'&&$next['access']['execution_id']===$f['access']['execution_id'],'Created another execution');}finally{$GLOBALS['pf_now']=$old;}});
pf_case('F HTTP verification capability marks verified and can be consumed only once',function(){ list($p,$h,$cookies)=pf_http_enroll();$f=pf_http_frame($p,$h,$cookies);$cap=pf_http_cap($f,'VERIFY_PARTICIPANT');$r=pf_http($p['public'],array(),null,$cap);pe_assert($r['status']===303,'Verification exchange');pe_assert((new L\Identity(pf_db()))->participant($f['access']['participant_id'])['verification_state']==='VERIFIED','Not verified');pe_assert(pf_http($p['public'],array(),null,$cap)['status']===403,'Replay accepted');pe_assert(pf_http($p['public'],$r['cookies'],null,$cap)['status']===303,'Matching replay lost session');});
pf_case('F HTTP expired credential rejects with generic response',function(){list($p,$h,$cookies)=pf_http_enroll();$f=pf_http_frame($p,$h,$cookies);$cap=pf_http_cap($f);pf_db()->transactional(function()use($cap){pf_db()->update('access_capabilities',array('expires_at'=>'2000-01-01 00:00:00'),pf_db()->prepare('token_hash=%s',hash('sha256',$cap)));});$r=pf_http($p['public'],array(),null,$cap);pe_assert($r['status']===403&&strpos($r['body'],$f['access']['participant_id'])===false,'Expired/private response');});
pf_case('F HTTP completed target direct link shows FINISHED and cannot resubmit',function(){list($p,$h,$cookies)=pf_http_enroll();$f=pf_http_frame($p,$h,$cookies);$target=$f['view']['next_action']['payload']['assessment_execution_id'];$cap=pf_http_cap($f,'ASSESSMENT_AVAILABLE',$target);$done=pf_http_finish_native($p,$h,$cookies,array('R_q1'=>'done'));pe_assert($done['data']['state']==='FINISHED','Not finished');$exchange=pf_http($p['public'],array(),null,$cap);$state=pf_http($p['public'],$exchange['cookies']);pe_assert($state['data']['state']==='FINISHED'&&strpos($state['data']['html'],'responses[')===false,'Completed reopened');});
pf_case('F HTTP removed response transport cannot mutate a longitudinal opportunity',function(){list($p,$h,$cookies)=pf_http_enroll('08',array('verification_policy'=>'ALLOW_UNVERIFIED','immediate_availability_policy'=>'SEND'));$f=pf_http_frame($p,$h,$cookies);$before=pf_owner()->view($f['access']['execution_id']);foreach(array('partial','next','back','submit') as $action){$r=pf_http($p['public'],$cookies,array('action'=>$action,'csrf'=>$f['csrf'],'command_id'=>'REMOVED_LONG_'.strtoupper($action),'expected_revision'=>$before['revision'],'responses'=>array('R_RISK'=>'9')));pe_assert($r['status']===422,'Removed form action accepted');}pe_equal($before['snapshot'],pf_owner()->view($f['access']['execution_id'])['snapshot']);});
pf_case('F HTTP V1 session link remains V1 after V2 and retirement while new email uses V2',function(){list($p,$h,$cookies)=pf_http_enroll();$f=pf_http_frame($p,$h,$cookies);$cap=pf_http_cap($f);$v2=pf_publish(null,array('reminder_offsets'=>array(7)),$p['definition']['study']['logical_id'],$p['public'],2);(new P\StudyVersionRepository(pf_db()))->retire($p['version']);$e=pf_http($p['public']);$r=pe_http_request($e,'enroll');$r['email']='v2@example.test';$new=pf_http($p['public'],$e['cookies'],$r);$b=pf_http_frame($p,$new,$new['cookies']?:$e['cookies']);pe_assert($b['access']['study_version_id']===$v2['version'],'New not V2');$exchange=pf_http($p['public'],array(),null,$cap);$old=pf_http($p['public'],$exchange['cookies']);$a=pf_http_frame($p,$old,$exchange['cookies']);pe_assert($a['access']['study_version_id']===$p['version'],'V1 lost');});
pf_case('F HTTP two devices restore the same Native assignment without a generic form',function(){list($p,$h,$cookies)=pf_http_enroll();$f=pf_http_frame($p,$h,$cookies);$cap=pf_http_cap($f);preg_match('/eipsi_native=([^"&]+)/',$h['data']['html'],$a);$exchange=pf_http($p['public'],array(),null,$cap);$b=pf_http($p['public'],$exchange['cookies']);preg_match('/eipsi_native=([^"&]+)/',$b['data']['html'],$next);pe_assert(!empty($a[1])&&$a[1]===$next[1],'Native assignment changed across devices');pe_assert(strpos($b['data']['html'],'name="responses[')===false,'Generic form remains');pe_assert(pf_http($p['public'],$cookies)['status']===200,'First device revoked');});
pf_case('F HTTP logout clears only own session and email then capability reaccesses',function(){list($p,$h,$cookies,$email)=pf_http_enroll();$f=pf_http_frame($p,$h,$cookies);$cap=pf_http_cap($f);$req=array('action'=>'logout','command_id'=>'LOGOUT_HTTP','csrf'=>$f['csrf']);$r=pf_http($p['public'],$cookies,$req);pe_assert($r['status']===200&&$r['data']['state']==='EMAIL_ENTRY','Logout failed');$after=pf_http($p['public'],$cookies);pe_assert($after['data']['state']==='EMAIL_ENTRY','Old session remained');$exchange=pf_http($p['public'],array(),null,$cap);$back=pf_http($p['public'],$exchange['cookies']);pe_assert($back['data']['state']==='OPEN_ASSESSMENT'&&pf_http_frame($p,$back,$exchange['cookies'])['access']['execution_id']===$f['access']['execution_id'],'Reaccess created science');});
pf_case('F HTTP bounded enrollment access resend and redemption use separate categories',function(){ $p=pf_publish();$e=pf_http($p['public']);$req=pe_http_request($e,'enroll');$req['email']='limit@example.test';$req['csrf']='valid-but-not-matching';for($i=0;$i<10;$i++)EIPSI_Rate_Limiter::consume('study.enrollment',$p['public'].'|127.0.0.1',10,60);$req['csrf']=L\Identity::csrf($p['public'],$e['cookies'][0]->value);$req['command_id']='LIMIT_FINAL';$r=pf_http($p['public'],$e['cookies'],$req);pe_assert($r['status']===429&&isset($r['headers']['retry-after']),'No atomic enrollment bound'); $req['action']='resend';$req['command_id']='RESEND_AFTER_LIMIT';$resend=pf_http($p['public'],$e['cookies'],$req);pe_assert($resend['status']!==429,'Shared resend bucket');$tampered=pf_http($p['public'],array(),null,'tampered');pe_assert($tampered['status']===403,'Redemption failed before its separate bound');});
pf_case('F HTTP new immediate participant verification email captured with correct recipient',function(){list($p,$h,$cookies,$email)=pf_http_enroll();pe_assert($h['data']['state']==='OPEN_ASSESSMENT','No immediate');$f=pf_http_frame($p,$h,$cookies);$old=$GLOBALS['pf_now'];$GLOBALS['pf_now']=(new L\Clock())->now();try{$before=count($GLOBALS['m0_mail']);pf_delivery(pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT')[0]);pe_assert(count($GLOBALS['m0_mail'])===$before+1,'Not captured');$mail=end($GLOBALS['m0_mail']);pe_assert(in_array($email,(array)$mail['to'],true)&&strpos($mail['subject'],'Confirm')!==false&&pf_link($mail)!=='','Wrong recipient/template/link');}finally{$GLOBALS['pf_now']=$old;}});

pf_case('Public HTML initial assessment completion errors and alias exclude all site chrome',function(){
 $path=WP_CONTENT_DIR.'/mu-plugins/eipsi-public-page-probe.php';wp_mkdir_p(dirname($path));$marker='EIPSI_SITE_CHROME_PROBE';pe_assert(!file_exists($path),'Probe already exists');file_put_contents($path,'<?php foreach(array("get_header","get_footer","wp_head","wp_footer") as $hook)add_action($hook,static function(){echo "EIPSI_SITE_CHROME_PROBE";});');
 try{
  $control=wp_remote_get('http://127.0.0.1/',array('timeout'=>15,'headers'=>array('Host'=>'127.0.0.1:18080'),'redirection'=>0));pe_assert(!is_wp_error($control)&&strpos(wp_remote_retrieve_body($control),$marker)!==false,'Theme probe inactive');
  $check=static function($r,$status)use($marker){pe_assert($r['status']===$status,'Wrong status '.$r['status']);pe_assert(stripos($r['body'],'<!doctype html>')!==false&&strpos($r['body'],'eipsi-public-page')!==false,'Missing standalone document');foreach(array($marker,'/themes/','wpadminbar') as $bad)pe_assert(strpos($r['body'],$bad)===false,'Site chrome leaked: '.$bad);};
  $p=pf_publish(null,array('initial_screen'=>L\InitialScreen::defaults()));$check(pe_http($p['public'],array(),null,array('Accept'=>'text/html')),200);
  $aliasStudy=$p['definition']['study']['logical_id'];$slug='public-probe-'.bin2hex(random_bytes(6));pf_db()->transactional(function()use($slug,$p){R\PublicUrl::reserve(pf_db(),$slug,$p['definition']['study']['logical_id'],$p['public']);});$alias=pe_http($slug,array(),null,array('Accept'=>'text/html'));$check($alias,200);pe_assert(strpos($alias['body'],'name="email"')!==false,'Alias entry failed');
  list($p,$h,$cookies)=pf_http_enroll();$check(pe_http($p['public'],$cookies,null,array('Accept'=>'text/html')),200);$done=pf_http_finish_native($p,$h,$cookies,array('R_q1'=>'standalone test'));pe_assert($done['data']['state']==='FINISHED','Not completed');$check(pe_http($p['public'],$cookies,null,array('Accept'=>'text/html')),200);
  $missing=pe_http('UNKNOWN_PUBLIC_'.bin2hex(random_bytes(6)),array(),null,array('Accept'=>'text/html'));pe_assert($missing['status']===404&&$missing['body']==='','Unknown study must have no participant page');
 }finally{unlink($path);if(isset($aliasStudy))R\PublicUrl::deleteStudy(pf_db(),$aliasStudy);}
});
pf_case('Email confirmation landing and expired link messages are standalone HTML',function(){
 list($p,$h,$cookies)=pf_http_enroll(null,array('initial_screen'=>L\InitialScreen::defaults()));$f=pf_http_frame($p,$h,$cookies);$cap=pf_http_cap($f);$exchange=pf_http($p['public'],array(),null,$cap,array('Accept'=>'text/html'),false);pe_assert($exchange['status']===303,'No clean capability redirect');$location=$exchange['headers']['location'];pe_assert(strpos($location,'eipsi_cap')===false,'Bearer leaked into redirect');$landing=wp_remote_get('http://127.0.0.1/?eipsi_study='.rawurlencode($p['public']).'&eipsi_confirm=1',array('timeout'=>15,'headers'=>array('Host'=>'127.0.0.1:18080'),'cookies'=>$exchange['cookies'],'redirection'=>0));$body=wp_remote_retrieve_body($landing);pe_assert(wp_remote_retrieve_response_code($landing)===200&&strpos($body,'eipsi-public-page')!==false&&strpos($body,'/themes/')===false&&strpos($body,'confirm_access')===false&&strpos($body,'Confirmar acceso')===false&&strpos($body,'Presioná Continuar')===false,'Intermediate confirmation or theme leaked');
 pf_db()->transactional(function()use($cap){pf_db()->update('access_capabilities',array('expires_at'=>'2000-01-01 00:00:00'),pf_db()->prepare('token_hash=%s',hash('sha256',$cap)));});$expired=pf_http($p['public'],array(),null,$cap,array('Accept'=>'text/html'),false);pe_assert($expired['status']===303&&strpos($expired['headers']['location'],'eipsi_initial=1')!==false&&strpos($expired['headers']['location'],'eipsi_notice=unavailable')!==false&&strpos($expired['headers']['location'],'eipsi_cap')===false,'No clean redirect to Initial Screen');$initial=wp_remote_get('http://127.0.0.1/?eipsi_study='.rawurlencode($p['public']).'&eipsi_initial=1&eipsi_notice=unavailable',array('timeout'=>15,'headers'=>array('Host'=>'127.0.0.1:18080'),'redirection'=>0));$initialHtml=wp_remote_retrieve_body($initial);pe_assert(wp_remote_retrieve_response_code($initial)===200&&strpos($initialHtml,'data-unavailable="1"')!==false&&strpos($initialHtml,'name="email"')!==false&&strpos($initialHtml,'role="alert"')!==false&&strpos($initialHtml,'Volver al inicio y solicitar un nuevo enlace')===false,'Initial Screen notice missing');

});
